  <script>
    (function(){
      const carousel=document.getElementById('testimonialCarousel');
      if(carousel){
      const track=carousel.querySelector('.carousel-track'),
      slides=carousel.querySelectorAll('.carousel-slide'),
      prevBtn=document.getElementById('carouselPrev'),
      nextBtn=document.getElementById('carouselNext'),
      dotsC=document.getElementById('carouselDots'),
      dots=dotsC?dotsC.querySelectorAll('.carousel-dot'):[],
      total=slides.length;
      let cur=0,autoI=null,tsx=0,tex=0;

      function go(i){if(i<0)i=total-1;if(i>=total)i=0;cur=i;
      track.style.transform='translateX(-'+cur*100+'%)';
      dots.forEach((d,j)=>{d.classList.toggle('active',j===cur);d.setAttribute('aria-selected',j===cur?'true':'false');});
      slides.forEach((s,j)=>s.setAttribute('aria-hidden',j!==cur?'true':'false'));
      }
      function startAP(){stopAP();autoI=setInterval(()=>go(cur+1),5000);}
      function stopAP(){if(autoI){clearInterval(autoI);autoI=null;}}

      if(prevBtn)prevBtn.addEventListener('click',()=>{go(cur-1);stopAP();startAP();});
      if(nextBtn)nextBtn.addEventListener('click',()=>{go(cur+1);stopAP();startAP();});
      dots.forEach((d,i)=>d.addEventListener('click',()=>{go(i);stopAP();startAP();}));
      carousel.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();go(cur-1);stopAP();startAP();}
      else if(e.key==='ArrowRight'){e.preventDefault();go(cur+1);stopAP();startAP();}});
      carousel.addEventListener('mouseenter',stopAP);carousel.addEventListener('mouseleave',startAP);
      carousel.addEventListener('focusin',stopAP);carousel.addEventListener('focusout',startAP);
      carousel.addEventListener('touchstart',e=>{tsx=e.changedTouches[0].screenX;},{passive:true});
      carousel.addEventListener('touchend',e=>{tex=e.changedTouches[0].screenX;const d=tsx-tex;
      if(Math.abs(d)>50){go(d>0?cur+1:cur-1);stopAP();startAP();}},{passive:true});
      go(0);startAP();
      }
    })();
  </script>

